"""Recognize only exact command wrappers generated by the former installer."""
from pathlib import Path
import re


def module_for(path, installation):
    path = Path(path)
    if path.is_symlink() or not path.is_file() or path.stat().st_size > 4096:
        return None
    try:
        text = path.read_text()
    except (OSError, UnicodeError):
        return None
    match = re.search(r' -m ([A-Za-z_]\w*(?:\.[A-Za-z_]\w*)*) "\$@"\n$', text)
    if not match:
        return None
    module = match[1]
    expected = f'''#!/usr/bin/env bash
set -e

cd "{installation}" || {{
  echo "Failed to cd to {installation}" >&2
  exit 1
}}

exec "{installation}/.venv/bin/python" -m {module} "$@"
'''
    return module if text == expected else None
